package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class JsonWriter_value_TriageGen0Test {

    private JsonWriter writer;
    private StringWriter sw;

    @Before
    public void setUp() {
        sw = new StringWriter();
        writer = new JsonWriter(sw);
    }

    @Test
    public void testValueTrue() throws IOException {
        writer.value(true);
        assertEquals("true", sw.toString());
    }

    @Test
    public void testValueFalse() throws IOException {
        writer.value(false);
        assertEquals("false", sw.toString());
    }

    @Test
    public void testValueNull() throws IOException {
        writer.value(null);
        assertEquals("null", sw.toString());
    }

    @Test
    public void testValueZero() throws IOException {
        writer.value(0);
        assertEquals("0", sw.toString());
    }

    @Test
    public void testValueOne() throws IOException {
        writer.value(1);
        assertEquals("1", sw.toString());
    }

    @Test
    public void testValueMinusOne() throws IOException {
        writer.value(-1);
        assertEquals("-1", sw.toString());
    }

    @Test
    public void testValueInfinity() throws IOException {
        writer.value(Double.POSITIVE_INFINITY);
        assertEquals("Infinity", sw.toString());
    }

    @Test
    public void testValueNegativeInfinity() throws IOException {
        writer.value(Double.NEGATIVE_INFINITY);
        assertEquals("-Infinity", sw.toString());
    }

    @Test
    public void testValueNaN() throws IOException {
        writer.value(Double.NaN);
        assertEquals("NaN", sw.toString());
    }

    @Test
    public void testValueBigDecimal() throws IOException {
        writer.value(new BigDecimal(1));
        assertEquals("1", sw.toString());
    }

    @Test
    public void testValueNullFloat() throws IOException {
        writer.value(Float.NaN);
        assertEquals("null", sw.toString());
    }

    @Test
    public void testValueNullDouble() throws IOException {
        writer.value(Double.NaN);
        assertEquals("null", sw.toString());
    }

    @Test
    public void testValueNullLong() throws IOException {
        writer.value(Long.MIN_VALUE);
        assertEquals("-9223372036854775808", sw.toString());
    }

    @Test(expected = IOException.class)
    public void testValueNullException() throws IOException {
        writer.value(null);
    }

    @Test
    public void testValueDeferredName() throws IOException {
        writer.name(".deferred");
        writer.value(true);
        assertEquals("{\"deferred\":true}", sw.toString());
    }
}
